sources = json.loads(Path("source.json").read_text())
answer = []
for source in sources:
    number = source["number"]
    detail = details[number]
    row = {k: source[k] for k in ("code_id", "source_id", "source_sha256", "number")}
    row.update(
        proposed_xml=Path(f"draft_{number}.xml").read_text().strip(),
        reason=detail["reason"],
        review_notes=detail["review_notes"],
        status="rewrite_draft",
    )
    if "removed_provisions" in detail:
        row.update(
            change_type="normative_reduction",
            reform_policy_id="editorial_direction_2026_10_19",
            removed_provisions=detail["removed_provisions"],
        )
    answer.append(row)

Path("answer.json").write_text(json.dumps(answer, ensure_ascii=False, indent=2) + "\n")
